on conflict (listing_id) do nothing;
update public._backup_1110_ebay_categories_tessy b set job_platform_fields = j.platform_fields
  from public.cross_post_jobs j where j.id = b.job_id and b.job_platform_fields is null;
select listing_id, offer_id, sku, empreinte, job_platform_fields is not null as job_sauve from public._backup_1110_ebay_categories_tessy order by 1;
